// ─────────────────────────────────────────────────────────────────────────────

export type TextBlock = { id: string; type: "text"; content: string };

export type Question = {
  id: string;
  questionType?:
  // Objective (auto-gradable)
  | "mcq"           // Multiple choice
  | "truefalse"     // True/False
  | "fillin"        // Fill in the blank
  | "matching"      // Match pairs
  | "ordering"      // Put items in correct order
  | "multiselect"   // Select all that apply
  // Subjective (requires manual grading)
  | "short"         // Short answer (1-3 sentences)
  | "essay"         // Long essay response
  | "coding"        // Code submission
  | "file_upload"   // Upload document/file
  | "drawing"       // Draw/diagram (image upload)
  | "audio"         // Audio response
  | "video";        // Video response

  question: string;              // Question text
  points?: number;               // Points worth (default: 1)
  rubric?: string;               // Grading rubric/guidelines for subjective questions

  // MCQ, multiselect
  options?: string[];
  correct?: number | number[];   // Single index or array of indices

  // Fill-in-the-blank
  blanks?: string[];             // Correct answers for each blank

  // Matching
  leftColumn?: string[];         // Items to match from
  rightColumn?: string[];        // Items to match to
  correctPairs?: Record<string, string>;  // Correct matches {left: right}

  // Ordering
  items?: string[];              // Items to put in order
  correctOrder?: number[];       // Correct sequence of indices

  // File uploads
  allowedFormats?: string[];     // e.g., ["pdf", "docx", "zip"]
  maxFileSize?: number;          // Max size in MB

  // Guidance
  sampleAnswer?: string;         // Model answer for reference
  explanation?: string;          // Explanation shown after grading
  hints?: string[];              // Optional hints
  timeLimit?: number;            // Time limit in seconds
};

export type QuizBlock = {
  id: string;
  type: "quiz";
  title?: string;          // Optional block title shown on pre-start screen
  questions: Question[];  // Multiple questions in one block
  // Legacy single-question fields (backward compat — still used in static content files)
  question?: string;
  options?: string[];
  correct?: number;
  blanks?: string[];
  sampleAnswer?: string;
  explanation?: string;
};

export type ChecklistBlock = { id: string; type: "checklist"; items: string[] };
export type CodeBlock = { id: string; type: "code"; language: string; code: string; caption?: string };
export type DocumentBlock = { id: string; type: "document"; url: string; title: string; fileType?: string; description?: string };
export type ImageBlock = { id: string; type: "image"; url: string; caption?: string; alt?: string };
export type VideoBlock = { id: string; type: "video"; url: string; title?: string; description?: string };
export type LearnBlock = TextBlock | QuizBlock | ChecklistBlock | CodeBlock | DocumentBlock | ImageBlock | VideoBlock;

export type LearnTopic = {
  id: string;
  title: string;
  description?: string;
  items?: string[]; // Curriculum items for 4th level display
  blocks: LearnBlock[];
};

export type IndicativeContent = {
  id: string;
  title: string;
  topics: LearnTopic[];
};

export type LearningOutcome = {
  number: number;
  title: string;
  learningHours: number;
  indicativeContents: IndicativeContent[];
};

export type LearnModule = {
  slug: string;
  moduleCode: string;
  title: string;
  tier: string;         // "l3" | "l4" | "l5"
  trackName: string;    // matches DB SkillTrack name
  xpReward: number;
  estimatedMinutes: number;
  description: string;
  outcomes: LearningOutcome[];
};

