// ─── Build LearnModule from curriculumContent + derive DB-matching topic IDs ──
//
// Topic IDs are derived as: seed-node-seed-track-{trackSlug}-0-t{n}
// This matches exactly what seed-content.ts writes to the DB.
//
import { getCurriculumContent } from "@/lib/curriculumContent";

function trackSlugFromName(trackName: string): string {
  return trackName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function buildModuleFromCurriculum(meta: {
  id: string; code: string; title: string; tier: string;
  trackName: string; xp: number;
}): LearnModule {
  const curriculum = getCurriculumContent(meta.trackName);
  const tSlug = trackSlugFromName(meta.trackName);
  const nodeId = `seed-node-seed-track-${tSlug}-0`;

  if (!curriculum) {
    return {
      ...buildFallbackModule(meta.id),
      moduleCode: meta.code,
      title: meta.title,
      tier: meta.tier,
      trackName: meta.trackName,
      xpReward: meta.xp,
    };
  }

  // Build outcomes/ICs/topics from curriculumContent, deriving nodeId-based topic IDs
  let flatTopicIndex = 0;
  const outcomes: LearningOutcome[] = curriculum.learningOutcomes.map((lo, loIdx) => ({
    number: loIdx + 1,
    title: lo.title,
    learningHours: lo.hours,
    indicativeContents: lo.topics.map((topic, topicIdx) => ({
      id: `${meta.id}-lo${loIdx + 1}-ic${topicIdx + 1}`,
      title: topic.title,
      topics: topic.subtopics.map((sub) => {
        // This ID must match what seed-content.ts wrote: nodeId + "-t" + (n)
        const n = ++flatTopicIndex;
        return {
          id: `${nodeId}-t${n}`,
          title: sub.title,
          description: sub.items?.join(" · ").slice(0, 100),
          items: sub.items || [], // Store items for student sidebar display
          blocks: [] as LearnBlock[], // populated at runtime from DB
        };
      }),
    })),
  }));

  return {
    slug: meta.id,
    moduleCode: meta.code,
    title: meta.title,
    tier: meta.tier,
    trackName: meta.trackName,
    xpReward: meta.xp,
    estimatedMinutes: curriculum.totalHours * 4,
    description: curriculum.purpose,
    outcomes,
  };
}

// Register all non-swdbd401 modules with curriculum-derived structure
for (const m of [...l3Modules, ...l4Modules, ...l5Modules]) {
  const mod = buildModuleFromCurriculum(m);
  MODULES.push(mod);
  // Also register the long-form slug that PassportClient generates
  // e.g. "l5-specific-modules-swdml501-machine-learning-application"
  // so both URLs resolve to the same module
  const altSlugs: string[] = [
    `l5-specific-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    `l4-specific-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    `l3-specific-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    `l5-general-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    `l4-general-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    `l3-general-modules-${m.code.toLowerCase()}-${m.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
  ].filter(s => s !== m.id);
  for (const alt of altSlugs) {
    if (!MODULES.find(x => x.slug === alt)) {
      MODULES.push({ ...mod, slug: alt });
    }
  }
}

// ─── Helper: get all topics flat for a module ─────────────────────────────────

export function getAllTopics(module: LearnModule): LearnTopic[] {
  return module.outcomes.flatMap((o) =>
    o.indicativeContents.flatMap((ic) => ic.topics)
  );
}

// ─── Helper: count all blocks across module ───────────────────────────────────

export function countAllBlocks(module: LearnModule): number {
  return getAllTopics(module).reduce((sum, t) => sum + t.blocks.length, 0);
}

// ─── Smart Fallback Generator ─────────────────────────────────────────────────

function buildFallbackModule(slug: string): LearnModule {
  const parts = slug.split("-");
  const levelStr = (parts[0] ?? "l4").toUpperCase();
  const titleWords = parts
    .slice(2)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
  const cleanTitle = titleWords.length > 0 ? titleWords : "Curriculum Module";
  const codeMatch = cleanTitle.match(/^([A-Z0-9]+)/);
  const moduleCode = codeMatch ? codeMatch[1] : levelStr;

  return {
    slug,
    moduleCode,
    title: cleanTitle,
    tier: parts[0] ?? "l4",
    trackName: `${levelStr} — Curriculum Module`,
    xpReward: 50,
    estimatedMinutes: 60,
    description: `Official Rwanda TVET curriculum module: ${cleanTitle}.`,
    outcomes: [
      {
        number: 1,
        title: `Analyze Foundations of ${cleanTitle}`,
        learningHours: 15,
        indicativeContents: [
          {
            id: `${slug}-lo1-ic1`,
            title: "Core Concepts",
            topics: [
              {
                id: `${slug}-lo1-ic1-t1`,
                title: "Topic 1.1: Core Concepts & Principles",
                blocks: [
                  {
                    id: `${slug}-lo1-ic1-t1-text1`,
                    type: "text",
                    content: `## Foundations of ${cleanTitle}\n\nWelcome to this TVET Rwanda curriculum module. Study the learning outcomes and complete each topic.`,
                  },
                  {
                    id: `${slug}-lo1-ic1-t1-chk1`,
                    type: "checklist",
                    items: [
                      "I have reviewed the core concepts",
                      "I understand the practical requirements",
                    ],
                  },
                ],
              },
            ],
          },
        ],
      },
    ],
  };
}

// ─── Public API ───────────────────────────────────────────────────────────────

export function getLearnModule(slug: string): LearnModule {
  const explicit = MODULES.find((m) => m.slug === slug);
  if (explicit) return explicit;

  const normalizedSlug = slug.toLowerCase();
  const looseMatch = MODULES.find(
    (m) =>
      normalizedSlug.includes(m.moduleCode.toLowerCase()) ||
      m.slug.includes(normalizedSlug)
  );
  if (looseMatch) return looseMatch;

  return buildFallbackModule(slug);
}

export default MODULES;
